#include <vector>
#include <cstddef>
#include <omp.h>

double productWithInverses(std::vector<double> const& x) {
    double product = 1.0;
    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(x.size());

    #pragma omp parallel for default(none) shared(x, n) reduction(* : product) schedule(static)
    for (std::ptrdiff_t i = 0; i < n; ++i) {
        product *= (i & 1) ? (1.0 / x[static_cast<std::size_t>(i)])
                           : x[static_cast<std::size_t>(i)];
    }

    return product;
}
